{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Safinamide absolute oral bioavailability was 95.0% (83.9–119.3%) after a 50 mg IR tablet in fasted subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Aprepitant geometric mean absolute oral bioavailability was 0.67 for an 80 mg fasted capsule, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Irbesartan absolute oral bioavailability was 82 ± 17% in healthy male volunteers after a 50 mg oral solution, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple human absolute bioavailability measurements, including safinamide 95%, aprepitant 67%, and irbesartan 82%, all exceed the 20% threshold; additional records for thalidomide, rolipram, balcinrenone, d-fenfluramine, and tegoprazan also support high oral bioavailability.",
  "evidence_gaps": [
    "Some records are qualitative or use unspecified bioavailability types, but the strongest numeric absolute bioavailability records consistently support high bioavailability.",
    "Aprepitant bioavailability estimates vary from 0.52 to 0.86, yet all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

